/**
 * @file types.ts
 * @description Holds TypeScript interface and enum definitions for the Universal Object Mapping (UOM) frontend.
 * Maps state fields of the LangGraph orchestrator, execution configurations, and platform types.
 */

/**
 * Represents validation outputs generated by compiling/executing source or target code in Daytona sandboxes.
 */
export interface QueryValidationResults {
	/** Total number of records returned by the query. */
	count?: number;
	/** First record sample returned by the database. */
	firstSample?: any;
	/** Last record sample returned by the database. */
	lastSample?: any;
	/** Any compilation or execution error messages from container stdout/stderr. */
	error?: string | null;
	/** Compiled SQL query string generated by Entity Framework or NHibernate. */
	sqlString?: string;
	/** Generated Cypher query string for Spring Data Neo4j. */
	cypher?: string;
	/** Generated MongoDB query JSON string. */
	mongoQuery?: string;
	/** Generated MongoDB aggregation pipeline JSON string. */
	mongoAggregation?: string;
}

/**
 * Output structure from semantic query equivalence checks using DeepDiff.
 */
export interface QueryEquivalenceDeepDiff {
	/** Custom mapping for LLM to understand which sample is which. */
	deepdiff_mapping?: any;
	/** Difference details in document counts. */
	count_diff?: any;
	/** Differences found between the first document samples. */
	first_sample_diff?: any;
	/** Differences found between the last document samples. */
	last_sample_diff?: any;
	/** Equivalence calculation runtime errors, if any. */
	error?: string | null;
}

/**
 * Configuration schema for the UOM Translator frontend.
 * Persisted in localStorage and passed to the LangGraph execution runtime.
 */
export interface UomConfig {
	/** Endpoint hostname/port for the local Ollama instance (e.g. http://localhost:11434). */
	ollamaHost: string;
	/** The specific model name to run (e.g. einfra/kimi-k2.6, ollama/qwen3-coder:30b). */
	model: string;
	/** Base URL for OpenAI-compatible LLM endpoints (e.g. e-INFRA AI services). */
	openaiApiUrl: string;
	/** API authorization key for OpenAI/e-INFRA endpoints. */
	openaiApiKey: string;
	/** Connection string to the source MS SQL Server instance. */
	mssqlConnectionString: string;
	/** URI for target MongoDB instance. */
	mongodbUri: string;
	/** Connection URI for target Neo4j Graph database. */
	neo4jUri: string;
	/** Password for authentication with Neo4j. */
	neo4jPassword: string;
	/** Endpoint URL of the Daytona API server. */
	daytonaApiUrl: string;
	/** API token for Daytona container orchestration. */
	daytonaApiKey: string;
	/** Target cloud region for Daytona sandbox containers (e.g. 'us', 'eu'). */
	daytonaTarget: "eu" | "us";
	/** Compilation sandbox execution limit in seconds. */
	daytonaTimeout: number;
	/** URI of the Database Toolbox MCP server wrapper. */
	dbToolboxUri?: string;
	/** URI of the MongoDB MCP server wrapper. */
	mongodbMcpUri?: string;
}

/**
 * Represents the complete execution state shared with the LangGraph state orchestrator.
 * Mirrors the Python LangGraph `State` schema exactly.
 */
export interface BackendState {
	/** Main conversational messages history including user prompts and agent responses. */
	messages?: any[];
	/** Input source code schema block provided by the user (C# EF Core / NHibernate / Dapper). */
	source_schema_code?: string | null;
	/** Input query C# code block provided by user. */
	source_query_code?: string | null;
	/** Desired translation scope ('schema', 'query', or 'both'). */
	translation_type?: string | null;
	/** Human-friendly name of the source framework (e.g. ".NET Entity Framework Core"). */
	source_target?: string | null;
	/** Explicit version parameter of the source framework. */
	source_target_version?: string | null;
	/** Human-friendly name of the target framework (e.g. "Java Spring Data MongoDB"). */
	destination_target?: string | null;
	/** Explicit version parameter of the target framework. */
	destination_target_version?: string | null;
	/** Generated target model/entity Java code translation. */
	translated_schema_code?: string | null;
	/** Generated target query Java code translation. */
	translated_query_code?: string | null;
	/** Extracted validation schemas for compile verification. */
	source_validation_schema_code?: string | null;
	/** Generated compilation project harness for .NET code. */
	source_validation_harness_code?: string | null;
	/** Generated target entities class representation for compiling. */
	target_validation_schema_code?: string | null;
	/** Generated compilation project harness for Java code. */
	target_validation_harness_code?: string | null;
	/** Accompanying notes or structural advice generated by the LLM advisor. */
	explanation_message?: string | null;
	/** Boolean indicator set when the State Graph terminates. */
	is_last_step?: boolean;
	/** Entrypoint class name for the C# validation harness. */
	source_validation_entry_type_name?: string | null;
	/** Entrypoint class name for the Java validation harness. */
	target_validation_entry_type_name?: string | null;
	/** Structured validation results returned from compile and execute tests on source code. */
	source_query_validation_results?: QueryValidationResults | null;
	/** Structured validation results returned from compile and execute tests on target code. */
	target_query_validation_results?: QueryValidationResults | null;
	/** Mapping of query keys to equivalence diff results. */
	query_equivalence_deep_diffs?: Record<
		string,
		QueryEquivalenceDeepDiff
	> | null;
	/** Live schema structures retrieved from the source database via MCP. */
	schema_context?: string;
	/** Isolated, system-level prompts used internally by the orchestrator. */
	translation_messages?: any[];
	/** Tracked iteration count of input parsing adjustments. */
	extraction_loop_count?: number;
	/** Tracked retry loop count for code generation compilation. */
	translation_loop_count?: number;
}

