/**
 * Supported framework types for ORM, ODM, and OGM mapping migrations.
 */
export enum FrameworkType {
	/** Relational source: Entity Framework Core */
	DOTNET_EFCORE = "dotnet_efcore",
	/** Relational source: NHibernate Core */
	DOTNET_NHIBERNATE = "dotnet_nhibernate",
	/** Relational source: Dapper SQL micro-ORM */
	DOTNET_DAPPER = "dotnet_dapper",
	/** NoSQL Document target: Spring Data MongoDB */
	JAVA_SPRING_DATA_MONGODB = "java_spring_data_mongodb",
	/** NoSQL Graph target: Spring Data Neo4j */
	JAVA_SPRING_DATA_NEO4J = "java_spring_data_neo4j",
}

/**
 * Underlying programming language runtimes.
 */
export enum LanguageType {
	/** Microsoft .NET Core (C#) */
	DOTNET = "dotnet",
	/** Oracle/OpenJDK Java (Java) */
	JAVA = "java",
}

/**
 * Translation operation scopes.
 */
export enum TranslationType {
	/** Schema classes/mappings translation only. */
	SCHEMA = "schema",
	/** Database Query translation only. */
	QUERY = "query",
	/** Combined schema definitions and executable query code. */
	BOTH = "both",
}

/**
 * Sandbox Docker container images provisioned via Daytona.
 */
export enum SandboxType {
	/** Sandbox container equipped with .NET 10 SDK and compilation utilities. */
	DOTNET_10_SANDBOX = "dotnet-10-sandbox",
	/** Sandbox container equipped with OpenJDK 25 and Maven/Gradle dependencies. */
	JAVA_25_SANDBOX = "java-25-sandbox",
}

/**
 * Composite structure holding execution details for supported frameworks.
 */
export interface FrameworkInfoType {
	/** Readable layout name of the framework. */
	name: string;
	/** Language ecosystem. */
	language: LanguageType;
	/** Sandbox image type used for compilations. */
	sandbox: SandboxType;
	/** True if the framework serves as an import source. */
	is_source: boolean;
	/** True if the framework serves as an export target. */
	is_target: boolean;
}

/**
 * Structured keys sent via LangGraph custom events.
 * Used to stream remote compilation progress, compile stdout/stderr logs, and container snapshot creation updates.
 */
export enum LanggraphCustomEventKeys {
	/** Notification when a new .NET Daytona container snapshot starts or completes creation. */
	DOTNET_SANDBOX_SNAPSHOT_CREATION = "dotnet_sandbox_snapshot_creation",
	/** Notification when a new Java Daytona container snapshot starts or completes creation. */
	JAVA_SANDBOX_SNAPSHOT_CREATION = "java_sandbox_snapshot_creation",
	/** Compilation/execution standard output logs from the .NET Daytona container. */
	DOTNET_SANDBOX_COMMAND_EXECUTION_STDOUT = "dotnet_sandbox_command_execution_stdout",
	/** Compilation/execution error logs from the .NET Daytona container. */
	DOTNET_SANDBOX_COMMAND_EXECUTION_STDERR = "dotnet_sandbox_command_execution_stderr",
	/** Compilation/execution standard output logs from the Java Daytona container. */
	JAVA_SANDBOX_COMMAND_EXECUTION_STDOUT = "java_sandbox_command_execution_stdout",
	/** Compilation/execution error logs from the Java Daytona container. */
	JAVA_SANDBOX_COMMAND_EXECUTION_STDERR = "java_sandbox_command_execution_stderr",
	/** Fallback event key for unrecognized event payloads. */
	UNKNOWN = "unknown",
}
